use serde::{Deserialize,Serialize}; use super::{receipt::Receipt,subject::SubjectId};
#[derive(Clone,Debug,Serialize,Deserialize)] pub struct ProcessEvent{pub id:String,pub activity:String,pub epoch:u64,pub actor:String,pub subject:String,pub decision:String,pub receipt:Option<String>}
impl ProcessEvent{pub fn from_receipt(r:&Receipt)->Self{Self{id:format!("event:{}",r.id),activity:"admission.decision".into(),epoch:r.epoch,actor:r.actor.clone(),subject:r.subject.key(),decision:r.decision.code().into(),receipt:Some(r.id.clone())}}}
#[derive(Clone,Debug,Serialize,Deserialize)] pub struct ProcessObject{pub id:String,pub object_type:String,pub revision:String} impl From<&SubjectId> for ProcessObject{fn from(s:&SubjectId)->Self{Self{id:s.key(),object_type:"exact-subject".into(),revision:s.revision.clone()}}}
#[derive(Clone,Debug,Default,Serialize,Deserialize)] pub struct OcelProjection{pub events:Vec<ProcessEvent>,pub objects:Vec<ProcessObject>} impl OcelProjection{pub fn observe(&mut self,r:&Receipt){if !self.objects.iter().any(|o|o.id==r.subject.key()){self.objects.push(ProcessObject::from(&r.subject))}self.events.push(ProcessEvent::from_receipt(r))}pub fn decision_counts(&self)->std::collections::BTreeMap<String,usize>{let mut m=std::collections::BTreeMap::new();for e in &self.events{*m.entry(e.decision.clone()).or_insert(0)+=1;}m}}